import{_ as t,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"CMS Page — Delete","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cms-pages-delete","title":"Delete a CMS Page","description":"Deletes a CMS page by IRI and returns a snapshot of the removed record.","query":"mutation DeleteCmsPage($input: deleteAdminCmsPageInput!) {\\n  deleteAdminCmsPage(input: $input) {\\n    adminCmsPage {\\n      id\\n      _id\\n      urlKey\\n      pageTitle\\n      metaTitle\\n      locale\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": { \\"id\\": \\"/api/admin/cms/pages/7\\" }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminCmsPage\\": {\\n      \\"adminCmsPage\\": {\\n        \\"id\\": \\"/api/admin/cms/pages/7\\",\\n        \\"_id\\": 7,\\n        \\"urlKey\\": \\"about-us\\",\\n        \\"pageTitle\\": \\"About Us\\",\\n        \\"metaTitle\\": \\"About Us\\",\\n        \\"locale\\": \\"en\\",\\n        \\"message\\": \\"CMS page deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/mutations/delete.md","filePath":"api/graphql-api/admin/cms/pages/mutations/delete.md","lastUpdated":1787290888000}'),s={name:"api/graphql-api/admin/cms/pages/mutations/delete.md"};function n(r,e,i,l,c,h){return o(),a("div",null,e[0]||(e[0]=[d('<h1 id="cms-page-—-delete" tabindex="-1">CMS Page — Delete <a class="header-anchor" href="#cms-page-—-delete" aria-label="Permalink to &quot;CMS Page — Delete&quot;">​</a></h1><p>Deletes a CMS page. Equivalent to <a href="/api/rest-api/admin/cms/pages-delete.html"><code>DELETE /api/admin/cms/pages/{id}</code></a>.</p><p>Replace the example <code>id</code> with a CMS page that exists in your store — <a href="/api/graphql-api/admin/cms/pages/queries/list.html"><code>adminCmsPages</code></a> lists valid ids.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>deleteAdminCmsPage</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>yes</td><td>Resource IRI — <code>/api/admin/cms/pages/{id}</code>.</td></tr></tbody></table><h2 id="what-it-returns" tabindex="-1">What it returns <a class="header-anchor" href="#what-it-returns" aria-label="Permalink to &quot;What it returns&quot;">​</a></h2><p>The mutation returns a <strong>snapshot of the deleted page</strong>, captured just before removal, so you can confirm what was deleted in the same round trip. The <strong>scalar</strong> fields all resolve — <code>id</code>, <code>_id</code>, <code>urlKey</code>, <code>pageTitle</code>, <code>htmlContent</code>, <code>metaTitle</code>, <code>metaKeywords</code>, <code>metaDescription</code>, <code>locale</code>. Select the fields you want to log or display.</p><h2 id="confirming-success-vs-failure" tabindex="-1">Confirming success vs. failure <a class="header-anchor" href="#confirming-success-vs-failure" aria-label="Permalink to &quot;Confirming success vs. failure&quot;">​</a></h2><p>Select the <strong><code>message</code></strong> field to get the human-readable success confirmation (<code>&quot;CMS page deleted successfully.&quot;</code>). The contract:</p><ul><li><strong>Success</strong> → <code>data.deleteAdminCmsPage.adminCmsPage</code> is non-null, <code>message</code> carries the confirmation, and <code>errors</code> is absent.</li><li><strong>Failure</strong> → <code>data.deleteAdminCmsPage</code> is <code>null</code> and the reason is in the top-level <strong><code>errors</code></strong> array (page not found, no permission, or a deletion failure). <code>message</code> is only populated on success.</li></ul><p>(<code>message</code> is <code>null</code> on read / list / detail queries — it is an action result, meaningful only on the delete mutation.)</p><h3 id="what-resolves-on-the-delete-payload" tabindex="-1">What Resolves on the Delete Payload <a class="header-anchor" href="#what-resolves-on-the-delete-payload" aria-label="Permalink to &quot;What Resolves on the Delete Payload&quot;">​</a></h3><p>Scalars come from an in-memory snapshot taken before the row was removed, so <code>urlKey</code>, <code>pageTitle</code>, and the rest still resolve — and <code>message</code> carries the confirmation text, which it does not on a read.</p><p>The <code>translations</code> and <code>channels</code> connections are re-read from the database instead, and the rows are already gone by then, so both return <strong>empty edges</strong>. Capture per-locale content with the <a href="/api/graphql-api/admin/cms/pages/queries/detail.html">detail query</a> before deleting if you need it.</p><p>Any <strong>301 redirects</strong> created earlier by renaming the page&#39;s <code>url_key</code> are left in place — deleting the page does not remove them, so an old slug keeps redirecting to a URL that no longer resolves. Remove them through <a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites-list.html">URL Rewrites</a> if that matters.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>Page ID not found</td><td>not-found error</td></tr><tr><td>Admin role lacks <code>cms.delete</code></td><td>permission error</td></tr></tbody></table>',19)]))}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
